import{z as s,x as l,o as e,c as d,q as n,j as r,D as B,d as a,s as i,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"债券指数化","description":"","frontmatter":{"title":"债券指数化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bm2-bond-indexing.md","filePath":"quant/bm2-bond-indexing.md","lastUpdated":1791063341000}'),C={name:"quant/bm2-bond-indexing.md"};function p(m,E,F,h,u,D){const t=l("Mermaid");return e(),d("div",null,[E[2]||(E[2]=n('<h1 id="债券指数化" tabindex="-1">债券指数化 <a class="header-anchor" href="#债券指数化" aria-label="Permalink to &quot;债券指数化&quot;">​</a></h1><div class="epigraph"><p>股票指数买一篮子就有了，债券指数只能近似：几千只场外券、多数日子不成交，复制注定是特征复制而非持仓复制。</p><footer>—— 据 Fabozzi, Bond Markets, Analysis and Strategies 指数化章节整理</footer></div><p><a href="/quant/bm2-ldi">上一课</a>把基准从市场指数换成负债函数；本课回到市场基准，但保留同一事实——基准是给定的，复制是受约束的。债券指数化要回答的问题因此不是「买什么」，而是：当逐券复制不可能时，跟踪误差应该落在哪个维度上，又该为消除它付多少成本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完全复制在债券市场是纸面方案：指数成员以万计，许多券最小面额大、无成交、做市商不报价；指数按月调仓，到期与降级的剔除券要在窗口期内接回。更要命的是计量层：场外成交稀薄，指数里相当一部分「价格」是估值商标记，实测跟踪误差里混着口径而非全是损失。于是目标改写为：在成本预算内，让组合与指数的<strong>风险特征</strong>重合——久期、利差久期、现金流分布、板块与评级权重——把逐券的差异留给抽样。这与 <a href="/quant/benchmark-tracking-error">跟踪误差的口径问题</a> 一脉相承：先说清误差怎么量，再谈怎么压。</p><p><span class="marginnote">直觉类比：股票指数复制像抄点名册——名单上每个名字都要买到；债券指数复制像拼马赛克——近看每块瓷砖都与原作不同，退后两步，整幅画的颜色分布（久期、板块、评级）与原作一致。「特征复制」就是名单不同、画像相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主流做法是分层抽样（单元法）：按久期桶、板块、评级、凸性把指数切成格子，每格内按市值加权选券，使组合的加权平均久期、利差久期与现金流分布对齐指数。格子是暴露的预算表——每个因子给一个容差带，越界即调仓。更进一步是用因子模型做跟踪误差最小化：给定协方差，在流动性约束下解出持仓子集。增强型指数化允许小幅偏离（久期 \\(\\pm\\) 一格、利差倾斜），用超额收益覆盖成本，但增强预算要写死：年化跟踪误差上限写进授权文件，否则「增强」会漂移成主动管理——漂了多远，可用 <a href="/quant/active-share">active-share 一类的集中度口径</a> 事后审计。</p>',8)),(e(),r(o,null,{default:B(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IX%5B%22%E6%8C%87%E6%95%B0%EF%BC%9A%E8%A7%84%E5%88%99%E5%8C%96%E7%9A%84%E5%80%BA%E5%88%B8%E5%85%A8%E9%9B%86%22%5D%20--%3E%20CE%5B%22%E5%88%86%E6%A0%BC%EF%BC%9A%E4%B9%85%E6%9C%9F%E3%80%81%E6%9D%BF%E5%9D%97%E3%80%81%E8%AF%84%E7%BA%A7%E3%80%81%E5%87%B8%E6%80%A7%22%5D%0A%20%20CE%20--%3E%20SA%5B%22%E6%AF%8F%E6%A0%BC%E6%8A%BD%E6%A0%B7%E5%B9%B6%E6%8C%89%E5%B8%82%E5%80%BC%E5%8A%A0%E6%9D%83%22%5D%0A%20%20SA%20--%3E%20FE%5B%22%E5%AF%B9%E9%BD%90%E7%89%B9%E5%BE%81%EF%BC%9A%E4%B9%85%E6%9C%9F%E3%80%81%E5%88%A9%E5%B7%AE%E4%B9%85%E6%9C%9F%E3%80%81%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%0A%20%20FE%20--%3E%20TE%5B%22%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%E5%88%86%E8%A7%A3%EF%BC%9A%E6%9A%B4%E9%9C%B2%E5%B7%AE%E3%80%81%E6%88%90%E6%9C%AC%E3%80%81%E4%BC%B0%E5%80%BC%E5%8F%A3%E5%BE%84%22%5D%0A%20%20TE%20--%3E%20EB%7B%22%E5%A2%9E%E5%BC%BA%E9%A2%84%E7%AE%97%E6%98%AF%E5%90%A6%E8%A6%86%E7%9B%96%E6%88%90%E6%9C%AC%22%7D%0A%20%20EB%20--%3E%20EN%5B%22%E5%A2%9E%E5%BC%BA%EF%BC%9A%E5%B0%8F%E5%B9%85%E5%81%8F%E7%A6%BB%EF%BC%8C%E8%AF%AF%E5%B7%AE%E4%B8%8A%E9%99%90%E5%86%99%E6%AD%BB%22%5D%0A%20%20EB%20--%3E%20PU%5B%22%E7%BA%AF%E5%A4%8D%E5%88%B6%EF%BC%9A%E5%8F%AA%E6%8E%A7%E6%9A%B4%E9%9C%B2%E5%AE%B9%E5%B7%AE%22%5D%0A%20%20EN%20--%3E%20TE%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("跟踪误差的构成决定了钱花在哪。抽样缺口是因子暴露之差，来自格子容量与选券质量；交易与持有成本来自调仓窗口的买卖价差，在剔除券的回补上最贵——这与 "),A("a",{href:"/quant/bond-liquidity-trace"},"债券成交与 TRACE 的流动性账"),a(" 直接相关：非活跃券的成本主要由价差而非佣金构成。第三块是「假误差」：估值时滞让指数收益滞后于可执行价格，实测误差因此被低估，经济上的误差比报表上大。还有一个结构性事实：债券指数按债务余额加权，等于按谁的债多谁权重大——最大发行人内生地主导指数，这是债券指数与股票指数在治理上的分岔，也解释了为什么单元法必须单设发行人集中度的格子。")],-1)),(e(),r(o,null,{default:B(()=>[i(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20TE%5B%22%E5%AE%9E%E6%B5%8B%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20E1%5B%22%E6%9A%B4%E9%9C%B2%E5%B7%AE%20%E5%9B%A0%E5%AD%90%E6%9A%B4%E9%9C%B2%E4%B9%8B%E5%B7%AE%22%5D%0A%20%20TE%20--%3E%20E2%5B%22%E4%BA%A4%E6%98%93%E6%88%90%E6%9C%AC%20%E8%B0%83%E4%BB%93%E4%BB%B7%E5%B7%AE%E4%B8%8E%E5%9B%9E%E8%A1%A5%22%5D%0A%20%20TE%20--%3E%20E3%5B%22%E4%BC%B0%E5%80%BC%E5%8F%A3%E5%BE%84%20%E6%8C%87%E6%95%B0%E4%BB%B7%E6%A0%BC%E6%BB%9E%E5%90%8E%22%5D%0A%20%20E1%20--%3E%20B%5B%22%E9%A2%84%E7%AE%97%E8%8A%B1%E5%9C%A8%E8%BF%99%20%E6%8A%BD%E6%A0%B7%E4%B8%8E%E8%B0%83%E4%BB%93%22%5D%0A%20%20E2%20--%3E%20B%0A%20%20E3%20--%3E%20A%5B%22%E4%B8%8D%E6%98%AF%E6%8D%9F%E5%A4%B1%20%E5%8F%AA%E8%83%BD%E6%8A%AB%E9%9C%B2%E4%B8%8E%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">数字实例：股票指数里单一公司权重超过 5% 就算高度集中；而国债占债券指数的权重可达三成以上，「单一发行人」是政府自己——这种集中度若发生在一家公司身上，任何股票指数都不可想象。发行人集中度格子因此必须单设。</span></p><p><span class="marginnote">按 TRACE 的成交记录，任意一个交易日里有相当比例的公司债没有任何成交；指数当日的报价多来自估值商标记。跟踪误差里因此有一部分是口径，不是损失——引用误差数字要先问计价来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单元法控制的是格子层面的暴露，格子内部的分散与个券风险不被控制；优化器给出的「最优子集」对协方差输入敏感，样本期一换权重就跳。指数化本身不免疫曲线风险——它就是要按指数的口径承担曲线风险，对冲基准之外的偏离属于增强，不属复制。调仓日效应（剔除券被全市场同时卖出）不是抽样能消除的，只能提前用流动性与成本模型定价。最后，指数成员规则（到期剔除、降级剔除）是指数的一部分：不读规则手册的复制者，会在每次调仓窗口意外地接住最贵的一棒。</p><p><span class="marginnote">常见误区：把指数调仓当成机械操作，「照单执行不会亏钱」。实际上全市场跟踪同一指数的基金会在同一窗口抢卖同一批剔除券，买方报价被压低——不提前按规则手册定价成本的复制者，接的正是全市场都在甩的那一棒。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>债券指数化的形态是特征复制：对齐久期、利差久期、现金流与板块权重，而非逐券持仓。</li><li>跟踪误差三块：暴露差、交易成本、估值口径，预算应花在前两块并审计第三块。</li><li>增强型指数化要有写死的误差上限，否则漂移成主动。</li><li>市值加权等于债务余额加权，最大发行人内生主导指数，集中度须单独设格。</li><li>出处：据 Fabozzi 指数化章节整理；误差口径与流动性背景见本站跟踪误差与 TRACE 相关课。</li></ul>',7))])}const f=s(C,[["render",p]]);export{b as __pageData,f as default};
